Method.Source:
    /// <summary>
    /// The Site and Warehouse Dimensions will be mandatory (enabled and not able to be disabled),
    /// </summary>
    /// <param name = "_mode"></param>
    void updateDesign(InventDimFormDesignUpdate _mode)
    {
        next updateDesign(_mode);

        // if user has METISPXDS role
        if (METisISPUser())
        {
            switch (_mode)
            {
                case InventDimFormDesignUpdate::Init          :
                    /*reserveOnOrdered = InventParameters::find().ReserveOnOrdered;
                    RowAvailReserveGroupPhysical.visible(!reserveOnOrdered);
                    RowAvailableForReservation.visible(reserveOnOrdered);*/
                    // No break
                case InventDimFormDesignUpdate::LinkActive    :
                    // CB501_ISP_Security
                    // Force the display dimensions to site and warehouse for ISP inventory transactions
                    //element.inventDimSetupObject().initFromCaller();
                    InventDimParm dimParmVisibleGridLocal;
                    dimParmVisibleGridLocal.InventSiteIdFlag = NoYes::Yes;
                    dimParmVisibleGridLocal.InventLocationIdFlag = NoYes::Yes;
                    this.inventDimSetupObject().parmDimParmVisibleGrid(dimParmVisibleGridLocal);
                    // Lock Site/Warehouse so they cannot be removed/unticked
                    this.inventDimSetupObject().parmDimParmLockedRightClick(dimParmVisibleGridLocal);

                    this.inventDimSetupObject().parmCtrlItemId(inventSum_ItemId);
                    if (#PdsCatchWeightEnabled)
                    {
                        this.inventDimSetupObject().parmCtrlCWItemId(InventSum_ItemId);
                    }
                    if (_mode == InventDimFormDesignUpdate::Init)
                    {
                        if (this.inventDimSetupObject().parmDimParmVisibleGrid().ItemIdFlag == NoYes::No)
                        {
                            itemName.visible(false);
                        }
                    }
                    this.inventDimSetupObject().parmDimParmVisible(this.inventDimSetupObject().parmDimParmVisibleGrid());
                    // No break
                case InventDimFormDesignUpdate::Active        :
                    /*this.inventDimSetupObject().formActiveSetup();
                    this.inventDimSetupObject().formSetControls(true,true);*/
                    break;

                default : throw error(strFmt("@SYS54195",funcName()));
            }
        }
    }
